export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  assertTimeZone(timeZone);
  const p = localParts(reference.getTime(), timeZone);
  return toIsoTimestamp(new Date(zonedToUtc(p.year, p.month, p.day, 0, timeZone)));
